/* All visible copy and notes are bilingual. Content follows ../program.md. */
const B = (bg, en) => ({ bg, en });
const CHAPTERS = [
  B('Въведение', 'Introduction'), B('01 · Цели и нужди', '01 · Goals & needs'),
  B('02 · Изследване', '02 · Research'), B('03 · Решения', '03 · Decisions'),
  B('04 · Strategy × AI', '04 · Strategy × AI'), B('Финал', 'Closing')
];
const SLIDES = [
  {id:'strategy',chapter:0,type:'cover',title:B('Strategy','Strategy'),subtitle:B('Преди първия пиксел.','Before the first pixel.'),caption:B('Бизнес цели. Човешки нужди. Обосновани решения.','Business goals. Human needs. Informed decisions.'),meta:B('ГОСТ ЛЕКЦИЯ · 190 МИНУТИ','GUEST LECTURE · 190 MINUTES'),notes:B('Въведение · 18:00–18:05. Днес работим върху решенията, които предхождат рисуването на екрани. За кого правим продукта? Кой проблем заслужава внимание? Резултатът е кратка стратегическа рамка, а не завършена стратегия.','Introduction · 18:00–18:05. Today we work on decisions that come before drawing screens. Who is the product for? Which problem deserves attention? The outcome is a short strategy framework, not a complete strategy.')},
  {id:'lecturer',chapter:0,type:'lecturer',kicker:B('ВАШИЯТ ЛЕКТОР','YOUR LECTURER'),title:B('Димитър Стоимчев','Dimitar Stoimchev'),role:B('Head of Product · Theoremus','Head of Product · Theoremus'),background:B('През последното десетилетие работя в бизнес анализа и продуктовото управление. От 2020 г. съм Head of Product в Theoremus и Product Owner в CNS. Преди това бях бизнес анализатор в Acronis, PXP Financial и Allergan.','Over the past decade, I’ve worked in business analysis and product management. Since 2020, I’ve been Head of Product at Theoremus and Product Owner at CNS. Previously, I worked in business analysis at Acronis, PXP Financial and Allergan.'),photo:'assets/dimitar-portrait.png',photoLabel:B('Портрет на Димитър Стоимчев','Portrait of Dimitar Stoimchev'),notes:B('Част от въведението, 18:00–18:05. Кратко представяне само на опита през последните 10 години (септември 2016–септември 2026). Theoremus и CNS: от ноември 2020; Acronis: май 2019–октомври 2020; PXP Financial: февруари 2018–май 2019; Allergan: частта от ролята Senior Business Analyst през 2016–февруари 2018. Източник: LinkedIn профилът, прегледан на 30 септември 2026.','Part of the introduction, 18:00–18:05. Summarises only the past 10 years (September 2016–September 2026). Theoremus and CNS: since November 2020; Acronis: May 2019–October 2020; PXP Financial: February 2018–May 2019; Allergan: the portion of the Senior Business Analyst role within 2016–February 2018. Source: LinkedIn profile, reviewed 30 September 2026.'),source:'https://www.linkedin.com/in/dimitar-stoimchev-31a36767/'},
  {id:'route',chapter:0,type:'roadmap',title:B('Маршрутът днес','Today’s route'),subtitle:B('18:00–21:10 · Три блока. Един общ казус.','18:00–21:10 · Three blocks. One shared case.'),times:['18:05–18:45','18:55–19:35','19:55–20:35','20:35–21:00'],items:[B('Цели и нужди','Goals & needs'),B('Изследване','Research'),B('Решения','Decisions'),B('Работа с AI','Working with AI')],caption:B('18:00–18:05 Въведение · 21:00–21:10 Финални въпроси\nПочивки: 18:45–18:55 (10 мин) · 19:35–19:55 (20 мин)','18:00–18:05 Introduction · 21:00–21:10 Closing questions\nBreaks: 18:45–18:55 (10 min) · 19:35–19:55 (20 min)'),notes:B('Покажи общата последователност: цел → нужда → доказателство → избор → проверка. Почивките са след първия и втория блок.','Explain the sequence: goal → need → evidence → choice → validation. Breaks follow blocks one and two.')},
  {id:'case',chapter:0,type:'case',title:B('Обядът, който не поръчахме','The lunch we didn’t order'),subtitle:B('Започваме поръчка. Защо не я завършваме?','We start an order. Why don’t we finish?'),items:[B('Неясна цена?','Unclear price?'),B('Късна доставка?','Late delivery?'),B('Проблем с плащането?','Payment issue?')],caption:B('Учебен казус · Всички числа и цитати са измислени','Teaching case · All numbers and quotes are fictional'),notes:B('Приложение за поръчка на обяд: 400 завършени от 1000 започнати поръчки. Причините още не са известни. Не решаваме предварително, че проблемът е цената.','Lunch delivery app: 400 completed out of 1,000 started orders. Causes are unknown. Do not decide in advance that price is the problem.')}
];

SLIDES.push(
  {id:'morning',chapter:1,type:'story',art:'morning',title:B('Сутринта преди автобуса','The morning before the bus'),subtitle:B('Кой проблем всъщност решаваме?','Which problem are we actually solving?'),bubble:B('По-силен будилник?','A louder alarm?'),alt:B('Родител с будилник, дете търси тетрадки, подготвена раница до вратата','A parent with an alarm, a child searching for notebooks, a prepared backpack by the door'),items:[B('Цел: излизаме в 7:40','Goal: leave at 7:40'),B('Нужда: намирам тетрадките','Need: find my notebooks'),B('Хипотеза: подготвям вечер','Hypothesis: pack the night before')],notes:B('Блок 1 · 18:05–18:08. Семейството всяка сутрин тича към автобуса. Родителят иска по-силен будилник, но детето не намира тетрадките. Разговорът изяснява нуждата. Целта е излизане до 7:40; KPI е броят навременни сутрини. Хипотезата: подготвянето на чантата вечер ще помогне. Поука: заявеното решение може да е различно от реалния проблем.','Block 1 · 18:05–18:08. The family rushes for the bus every morning. A parent wants a louder alarm, but the child cannot find their notebooks. Conversation reveals the need. Goal: leave by 7:40. KPI: mornings leaving on time. Hypothesis: packing the night before will help. The requested solution may not address the actual problem.')},
  {id:'ux-strategy',chapter:1,type:'flow',title:B('UX стратегия','UX strategy'),subtitle:B('Желано бъдещо преживяване. Ясни избори днес.','A desired future experience. Clear choices today.'),items:[[B('Визия','Vision'),B('Накъде искаме да стигнем?','Where do we want to go?')],[B('Цели','Goals'),B('Как ще разпознаем напредъка?','How will we recognise progress?')],[B('План','Plan'),B('Какво ще направим първо?','What will we do first?')]],notes:B('Topic 1.1 · 3 мин. UX стратегията е план за по-добро преживяване в определен период. Визията за казуса е уверен избор на обяд в кратка почивка. Планът започва с проучване на отказите, избор на проблем и проверка. Списъкът с функции не обяснява посока или успех.','Topic 1.1 · 3 min. UX strategy is a plan to improve experience over a defined period. Our vision is confidently choosing lunch in a short break. Investigate abandonment, select a problem and validate an approach. A feature list alone does not explain direction or success.'),source:'https://www.nngroup.com/articles/ux-strategy/'},
  {id:'intersection',chapter:1,type:'venn',title:B('Три гледни точки','Three perspectives'),statement:B('Полезно за хората. Устойчиво за бизнеса. Възможно за изпълнение.','Useful to people. Viable for the business. Feasible to deliver.'),detail:B('Стратегията свързва нуждите, целите и ограниченията.','Strategy connects needs, goals and constraints.'),notes:B('В рамките на Topic 1.1. Дизайнерът свързва потребителски нужди, цели на организацията и технологични възможности. Търсим обща посока, а не изолирана оптимизация. Схемата стъпва на пресечната точка от стр. 10 на оригиналната презентация.','Within Topic 1.1. Designers connect user needs, organisational goals and technical feasibility. Seek a shared direction, rather than optimising one perspective in isolation. Based on page 10 of the supplied presentation.')},
  {id:'business-goals',chapter:1,type:'metric',title:B('Как изглежда успехът?','What does success look like?'),kicker:B('БИЗНЕС ЦЕЛИ · KPI','BUSINESS GOALS · KPI'),items:[[B('3 месеца','3 months'),B('срок','timeframe')],[B('+10 п.п.','+10 pp'),B('промяна в конверсията','conversion change')],[B('Без ръст','No increase'),B('оплаквания / 100 поръчки','complaints / 100 orders')]],caption:B('Учебна цел, а не прогноза за резултат','A fictional target, not a predicted result'),notes:B('Topic 1.2 · 6 минути за целите, конверсията и задържането. Бизнес целта е желаният резултат в срок. Метриката е измерима характеристика. KPI е избраният ключов показател. Baseline = начална стойност; target = целева стойност. От 40% на 50% е +10 процентни пункта, или 25% относителен ръст. Контролният показател пази от нежелани ефекти.','Topic 1.2 · 6 minutes across goals, conversion and retention. A business goal is a desired outcome within a timeframe. A metric is a measurement. A KPI is a metric selected to track progress. Baseline is the starting value; target is the desired value. 40% to 50% is +10 percentage points, or a 25% relative increase. Track complaints per 100 orders as a guardrail.')},
  {id:'conversion',chapter:1,type:'waffle',title:B('Conversion rate','Conversion rate'),subtitle:B('Завършено действие / ясно определена начална група','Completed action / a clearly defined starting group'),value:40,formula:B('400 / 1000 × 100 = 40%','400 / 1,000 × 100 = 40%'),detail:B('Едно квадратче = 10 започнати поръчки. Зелените = завършените.','One square = 10 started orders. Green = completed orders.'),caption:B('A1 · Учебни данни · Причините за останалите 60% не са известни','A1 · Fictional data · The reasons behind the other 60% are unknown'),notes:B('В рамките на Topic 1.2. Започната поръчка = отворена стъпка за потвърждение, отчетена веднъж за уникална поръчка. Завършена = потвърдена поръчка от същата начална група. Правилото и периодът трябва да са еднакви. Процентът не разкрива причината за отказите.','Within Topic 1.2. Started means reaching confirmation, counted once per unique order. Completed means confirmed within the same starting group. Keep the counting rule and period consistent. The percentage does not explain abandonment.')},
  {id:'retention',chapter:1,type:'waffle',title:B('Retention','Retention'),subtitle:B('Кой се връща за още?','Who comes back?'),value:30,round:true,formula:B('30 от 100 нови клиенти','30 out of 100 new customers'),detail:B('Поръчват отново през следващите 30 дни.','Order again within the next 30 days.'),caption:B('Учебен пример · Винаги определяме групата, действието и периода','Fictional example · Define the group, the action and the period'),notes:B('В рамките на Topic 1.2. Retention е делът от определена начална група, който повтаря значимо действие в избран период. В оригиналните слайдове 44–49 Duolingo илюстрира конверсия чрез абонамент и връщане чрез поредица от дни на учене. Самите екрани не доказват ефекта им.','Within Topic 1.2. Retention is the share of a defined starting group repeating a meaningful action in a chosen period. The original slides 44–49 use Duolingo subscriptions and learning streaks to illustrate conversion and return behaviour. Screens alone do not prove their impact.')},
  {id:'needs',chapter:1,type:'compare',title:B('Нужда ≠ функция','Need ≠ feature'),labels:[B('ЗАЯВЕНО РЕШЕНИЕ','REQUESTED SOLUTION'),B('ПОТРЕБИТЕЛСКА НУЖДА','USER NEED')],left:B('„Искам филтър за бърза доставка.“','“I want a fast-delivery filter.”'),right:B('„Искам обяд преди следващата среща.“','“I need lunch before my next meeting.”'),leftNote:B('Един възможен подход','One possible approach'),rightNote:B('Резултат в конкретна ситуация','An outcome in a specific situation'),notes:B('Topic 1.3 · 5 минути за нужди, сегмент и контекст. Нуждата е резултатът, който човек иска да постигне. Функцията е един възможен механизъм. Битов пример: по-голям куфар срещу нуждата да пренеса багаж за три дни без допълнителна такса. Не приемаме заявката автоматично за задача.','Topic 1.3 · 5 minutes for needs, segments and context. A need is an outcome someone wants to achieve. A feature is one possible mechanism. Everyday example: a bigger suitcase versus carrying three days of luggage without an extra fee. Do not turn every request directly into a feature.')},
  {id:'context',chapter:1,type:'flow',title:B('Контекстът променя нуждата','Context changes the need'),items:[[B('30 минути','30 minutes'),B('Кратка обедна почивка','A short lunch break')],[B('Телефон','Phone'),B('Избор между две срещи','Choosing between meetings')],[B('Фиксиран час','Fixed deadline'),B('Не мога да изчакам','I cannot wait longer')]],caption:B('Сегмент: хора с ограничен времеви прозорец · Не просто възрастова група','Segment: people with a limited time window · More than an age group'),notes:B('В рамките на Topic 1.3. Контекстът включва време, място, устройство и ограничения. Сегментът обединява сходни релевантни нужди или поведение. Pain point е пречка по пътя. Двама души на една възраст могат да поръчват за напълно различни ситуации. Попитай: „Бутон за повторна поръчка“ нужда ли е, или решение?','Within Topic 1.3. Context includes time, place, device and constraints. A segment shares relevant needs or behaviour. A pain point is an obstacle. People of the same age may order in very different circumstances. Ask whether “a reorder button” is a need or a solution.')},
  {id:'stakeholders',chapter:1,type:'list',title:B('Stakeholders','Stakeholders'),subtitle:B('Кой влияе на продукта? Кой е засегнат?','Who influences the product? Who is affected?'),items:[[B('Продуктов мениджър','Product manager'),B('Цели и приоритети','Goals and priorities')],[B('Поддръжка','Customer support'),B('Повтарящи се оплаквания','Recurring complaints')],[B('Разработка','Engineering'),B('Данни и технически ограничения','Data and technical constraints')],[B('Операции','Operations'),B('Какво реално можем да обещаем','What we can actually promise')]],notes:B('Topic 1.4 · 4 минути с въпросите на следващия слайд. Stakeholder е човек или група, които влияят на продукта или са засегнати от него. Ограничение = срок, бюджет, техническа възможност. Зависимост = необходима работа или информация от друг човек.','Topic 1.4 · 4 minutes including the next slide. A stakeholder influences the product or is affected by it. Constraints include time, budget and technical capability. A dependency requires work or information from another person.')},
  {id:'stakeholder-interview',chapter:1,type:'list',title:B('Разговорът преди решението','The conversation before the decision'),kicker:B('STAKEHOLDER INTERVIEWS','STAKEHOLDER INTERVIEWS'),items:[B('Какво трябва да се промени?','What needs to change?'),B('Как ще измерим успеха?','How will we measure success?'),B('Какво знаем — и откъде?','What do we know — and how?'),B('Какво ни ограничава?','What constrains us?')],caption:B('Мнението за потребителите все още е допускане','An opinion about users is still an assumption'),notes:B('В рамките на Topic 1.4. Изясни краткосрочни цели, измерване, източници, ограничения и кой още трябва да участва. „Потребителите искат по-ниски цени“ трябва да се подкрепи с доказателства. Stakeholder интервютата обясняват организацията; user interviews — преживяването на хората.','Within Topic 1.4. Clarify goals, measurement, sources, constraints and who else should participate. “Users want lower prices” needs evidence. Stakeholder interviews explain the organisation; user interviews explore people’s experiences.')},
  {id:'hypothesis',chapter:1,type:'flow',title:B('Факт. Допускане. Хипотеза.','Fact. Assumption. Hypothesis.'),items:[[B('Знаем','We know'),B('400 от 1000 поръчки са завършени.','400 of 1,000 orders are completed.')],[B('Предполагаме','We assume'),B('Неясните такси водят до отказ.','Unclear fees cause abandonment.')],[B('Проверяваме','We test'),B('По-ранна обща цена → повече поръчки?','Earlier total price → more orders?')]],caption:B('Учебен пример · Причината още не е установена','Fictional example · The cause is not yet established'),notes:B('Topic 1.5 · 4 мин. Формулировката на проблема назовава кого затруднява какво, в какъв контекст и с каква последица. Допускането е непроверено убеждение. Хипотезата е проверимо предположение. За проверка уточняваме аудитория, промяна, показател и период. Приемаме и опровергаващ резултат.','Topic 1.5 · 4 min. A problem statement identifies who struggles, with what, in which context and with what consequence. An assumption is unverified. A hypothesis can be tested. Define the audience, change, metric and period; accept disconfirming results.')},
  {id:'exercise-1',chapter:1,type:'exercise',title:B('Една страница стратегия','One page of strategy'),kicker:B('УПРАЖНЕНИЕ 01 · ПО ДВОЙКИ','EXERCISE 01 · IN PAIRS'),subtitle:B('Дизайнер × продуктов мениджър','Designer × product manager'),minutes:10,items:[[3,B('Разговор за цел, успех и ограничения','Interview about goals, success and constraints')],[5,B('Цел · KPI · нужда · ограничение · допускане','Goal · KPI · need · constraint · assumption')],[2,B('Споделете и проверете логиката','Share and check the logic')]],caption:B('Нуждата описва резултат, не функция','The need describes an outcome, not a feature'),notes:B('18:30–18:40. Карта за PM: 400/1000 завършени; желана конверсия 50% за три месеца; съмнение за таксите без потвърждение; може да се промени интерфейсът, но не цените или системата за доставки. Без ръст на оплаквания на 100 поръчки. Дизайнерът пита, PM не измисля липсващи факти. Пример: нужда от навременна преценка на обща цена и срок.','18:30–18:40. PM card: 400/1,000 complete; target 50% in three months; unverified concern about fees; UI can change, but not prices or delivery prediction. No increase in complaints per 100 orders. Designer asks questions; PM does not invent missing information. Example need: assess total cost and timing early.')},
  {id:'discussion-1',chapter:1,type:'question',title:B('Нека обсъдим','Let’s discuss'),kicker:B('БЕСЕДА · 5 МИНУТИ','DISCUSSION · 5 MINUTES'),items:[B('Повече поръчки = по-добро преживяване?','More orders = a better experience?'),B('А ако бизнесът иска да скрием таксата?','What if the business wants to hide the fee?')],notes:B('18:40–18:45. По две минути на въпрос и една за контролен показател. Ръстът може да идва от промоция, трафик или подвеждащо представяне. Следим отмени, оплаквания и повторно използване. Търсим устойчив резултат, включително след поръчката.','18:40–18:45. Two minutes per question; one minute to choose a guardrail. Growth may result from promotions, traffic or misleading presentation. Track cancellations, complaints and repeat use. Seek a sustainable result after checkout, too.')},
  {id:'break-1',chapter:1,type:'break',title:B('Почивка','Take a break'),subtitle:B('18:45–18:55 · Връщаме се в 18:55.','18:45–18:55 · Back at 18:55.'),minutes:10,caption:B('Кое допускане е най-важно да проверим?','Which assumption matters most to test?'),notes:B('18:45–18:55. Обяви точния час за връщане. Таймерът започва само при натискане на Старт.','18:45–18:55. Announce the return time. The timer starts only when you press Start.')}
);

SLIDES.push(
  {id:'picnic',chapter:2,type:'story',art:'picnic',title:B('Пикникът с „идеалното“ меню','The picnic with the “perfect” menu'),subtitle:B('Двама приятели не са всички гости.','Two friends are not all your guests.'),bubble:B('Всички искат същото?','Everyone wants the same?'),alt:B('Организатор на пикник сравнява мнението на двама приятели с нуждите на цялата група','A picnic organiser compares two friends’ opinions with the whole group’s needs'),items:[B('Извадка: кого питаме?','Sample: who do we ask?'),B('Интервю: какво се е случило?','Interview: what happened?'),B('Анкета: колко и какво?','Survey: how many and what?')],notes:B('Блок 2 · 18:55–18:58. Мая пита двама приятели за сандвичи с месо и приема отговорите за мнение на всички. Интервю за предишния пикник показва, че някои са останали без подходяща храна. Анкета до всички поканени уточнява присъствие и предпочитания. Поука: въпросът определя метода; извадката определя границите.','Block 2 · 18:55–18:58. Maya asks two friends about meat sandwiches and assumes everyone agrees. An interview about the last picnic reveals that some guests had no suitable food. A survey clarifies attendance and preferences. The question determines the method; the sample limits the conclusions.')},
  {id:'research-methods',chapter:2,type:'methods',title:B('Въпросът избира метода','The question chooses the method'),items:[[B('КАЧЕСТВЕНИ · ЗАЯВЕНИ','QUALITATIVE · REPORTED'),B('Интервю','Interview'),B('Как протече последната поръчка?','How did the last order go?')],[B('КОЛИЧЕСТВЕНИ · ЗАЯВЕНИ','QUANTITATIVE · REPORTED'),B('Анкета','Survey'),B('Колко от отговорилите срещат проблема?','How many respondents report the issue?')],[B('КАЧЕСТВЕНИ · НАБЛЮДАВАНИ','QUALITATIVE · OBSERVED'),B('Тест на задача','Usability test'),B('Разбира ли човекът общата цена?','Does the person understand the total?')],[B('КОЛИЧЕСТВЕНИ · РЕГИСТРИРАНИ','QUANTITATIVE · RECORDED'),B('Продуктови данни','Product analytics'),B('На коя стъпка се прекъсва поръчката?','Where does the order stop?')]],caption:B('Методите могат да събират различни типове данни; това са примерни употреби','Methods can collect different data types; these are example uses'),notes:B('Topic 2.1 · 4 мин. Research е системно събиране и анализ по конкретен въпрос. Качествените данни дават контекст, количествените — измерване. Интервюто събира разкази, не директно наблюдение. Анкетата може да включва отворени качествени отговори. „Винаги гледам цената“ може да се различава от поведението при задача.','Topic 2.1 · 4 min. Research systematically gathers and analyses information. Qualitative data provides context; quantitative data provides measurement. Interviews collect reports, not direct observation. Surveys can also include qualitative open responses. Reported habits can differ from observed behaviour.'),source:'https://www.nngroup.com/articles/which-ux-research-methods/'},
  {id:'research-plan',chapter:2,type:'flow',title:B('Кратък изследователски план','A short research plan'),items:[[B('Решение','Decision'),B('Какво трябва да решим?','What do we need to decide?')],[B('Неизвестно','Unknown'),B('Какво трябва да научим?','What do we need to learn?')],[B('Хора','People'),B('Кой има релевантен опит?','Who has relevant experience?')],[B('Метод','Method'),B('Как ще научим това?','How will we learn it?')]],caption:B('„Десет интервюта“ е задача. Какво решение ще подпомогнат?','“Ten interviews” is an activity. What decision will they inform?'),notes:B('Topic 2.2 · 3 мин. Изследователският въпрос е за екипа; въпросът към участника трябва да извика конкретен разказ. За екипа: „Какво затруднява оценката на общата цена?“ Към участника: „В кой момент разбра колко ще платиш?“ Планът включва изход, организация и ограничения.','Topic 2.2 · 3 min. The research question serves the team; interview questions elicit concrete experiences. Team question: “What makes the total hard to assess?” Participant question: “When did you understand how much you would pay?” Include outputs, logistics and limitations.')},
  {id:'sample-bias',chapter:2,type:'compare',title:B('Кого не сме чули?','Who haven’t we heard?'),labels:[B('УДОБНА ИЗВАДКА','CONVENIENCE SAMPLE'),B('РЕЛЕВАНТНО ПОВЕДЕНИЕ','RELEVANT BEHAVIOUR')],left:B('Нашите приятели. Доволните клиенти.','Our friends. Happy customers.'),right:B('Поръчали. Отказали се. Не се върнали.','Completed. Abandoned. Never returned.'),leftNote:B('Лесен достъп ≠ пълна картина','Easy access ≠ a complete picture'),rightNote:B('Търсим различни ситуации','Look for different situations'),notes:B('Topic 2.3 · 3 минути с етиката на следващия слайд. Извадката са реално включените хора. Bias е системно отклонение. Confirmation bias е предпочитание към подкрепящи данни. Няма универсално достатъчен брой участници. Записваме кого сме включили и кого сме пропуснали.','Topic 2.3 · 3 minutes including the next slide. The sample contains those actually included. Bias is systematic distortion. Confirmation bias favours supporting evidence. There is no universal sufficient sample size. Record who was included and who was missed.')},
  {id:'consent',chapter:2,type:'flow',title:B('Съгласие и грижа за данните','Consent and care for data'),items:[[B('Обясняваме','Explain'),B('Цел, време, употреба на данните','Purpose, duration, use of data')],[B('Питаме','Ask'),B('Съгласие преди запис','Consent before recording')],[B('Ограничаваме','Minimise'),B('Само нужните данни','Only the data we need')]],caption:B('Участникът може да пропусне въпрос или да прекрати','Participants can skip a question or stop'),notes:B('В рамките на Topic 2.3. Дайте избор за участие и запис. Премахнете идентифициращи детайли от споделени бележки. Учебните разговори не се записват и не представляват пазарно изследване.','Within Topic 2.3. Give participants a choice about participation and recording. Remove identifying details from shared notes. Classroom interviews need no recording and are not market research.')},
  {id:'interview',chapter:2,type:'flow',title:B('Интервюто следва преживяването','An interview follows the experience'),items:[[B('Разказ','Story'),B('Разкажи за последния път…','Tell me about the last time…')],[B('Контекст','Context'),B('Къде беше? С колко време?','Where were you? How much time?')],[B('Уточнение','Follow-up'),B('Какво направи след това?','What did you do next?')]],notes:B('Topic 2.4 · 6 минути за интервюто и следващите два слайда. Отвореният въпрос кани към разказ. Затвореният уточнява факт. Probe задълбочава. Дайте време; не защитавайте продукта. Точните цитати се отделят от интерпретацията.','Topic 2.4 · 6 minutes across this and the next two slides. Open questions invite a story; closed questions clarify a fact; probes go deeper. Allow silence and do not defend the product. Separate exact quotes from interpretation.'),source:'https://www.nngroup.com/articles/user-interviews/'},
  {id:'leading-question',chapter:2,type:'compare',title:B('Не подсказвай отговора','Don’t lead the answer'),labels:[B('ПОДВЕЖДАЩ ВЪПРОС','LEADING QUESTION'),B('НЕУТРАЛЕН ВЪПРОС','NEUTRAL QUESTION')],left:B('„Не те ли объркаха таксите?“','“Didn’t the fees confuse you?”'),right:B('„Как разбра общата сума?“','“How did you work out the total?”'),leftNote:B('Вкарваме нашето обяснение','We introduce our own explanation'),rightNote:B('Оставяме място за собствен разказ','We leave room for their account'),strike:true,reveal:true,notes:B('В рамките на Topic 2.4. Покани един кратък отговор преди показването. Друг пример: „Би ли използвал удобния ни филтър?“ → „Как последния път прецени кое ще пристигне навреме?“ Заявеното намерение не доказва бъдеща употреба.','Within Topic 2.4. Ask for one quick alternative before revealing. Another example: “Would you use our convenient filter?” → “How did you judge what would arrive on time last time?” Stated intention does not prove future use.'),source:'https://www.nngroup.com/articles/interview-questions-mistakes/'},
  {id:'interview-guide',chapter:2,type:'list',title:B('Слушай. После уточнявай.','Listen. Then follow up.'),items:[B('„Как избра?“','“How did you choose?”'),B('„Какво очакваше?“','“What did you expect?”'),B('„Когато казваш „скъпо“…?“','“When you say ‘expensive’…?”'),B('„Как приключи ситуацията?“','“How did it end?”')],caption:B('Точен цитат ≠ наша интерпретация','An exact quote ≠ our interpretation'),notes:B('В рамките на Topic 2.4. Започни: „Няма правилни и грешни отговори. Можеш да пропуснеш всеки въпрос.“ Не обяснявай интерфейса вместо участника. Потърси пример, а не общо мнение. Следи за противоречащи случаи.','Within Topic 2.4. Open with: “There are no right or wrong answers. You can skip any question.” Do not explain the interface for the participant. Ask for an example rather than a general opinion. Look for disconfirming cases.')},
  {id:'surveys',chapter:2,type:'list',title:B('Добрата анкета','A good survey'),items:[[B('Един въпрос → едно нещо','One question → one thing'),B('Без двойни въпроси','No double-barrelled questions')],[B('Конкретен период','A specific period'),B('„През последните 7 дни…“','“In the past 7 days…”')],[B('Неутрални възможности','Neutral response options'),B('Ясни, балансирани, без припокриване','Clear, balanced, non-overlapping')],[B('Пробен преглед','A pilot review'),B('Разбират ли хората въпросите?','Do people understand the questions?')]],notes:B('Topic 2.5 · 6 минути със следващите два слайда. Анкетата събира отговори по общ набор въпроси. Пример за честота: 0 / 1–2 / 3–4 / 5+ / Не помня за последните 7 дни. Скала е подреден набор оценки. Добавяйте „друго“, „не помня“ или „не е приложимо“, когато е нужно.','Topic 2.5 · 6 minutes including the next two slides. A survey uses a common set of questions. Frequency example: 0 / 1–2 / 3–4 / 5+ / Don’t remember over the past seven days. A scale is an ordered set of ratings. Add other, don’t remember or not applicable where appropriate.'),source:'https://www.pewresearch.org/writing-survey-questions/'},
  {id:'double-question',chapter:2,type:'compare',title:B('Лесно и приятно?','Easy and pleasant?'),labels:[B('ДВЕ ОЦЕНКИ В ЕДНО','TWO RATINGS IN ONE'),B('ДВА ОТДЕЛНИ ВЪПРОСА','TWO SEPARATE QUESTIONS')],left:B('„Колко лесно и приятно беше поръчването?“','“How easy and pleasant was ordering?”'),right:B('„Колко лесно?“\n„Колко приятно?“','“How easy?”\n“How pleasant?”'),leftNote:B('Лесно може да е неприятно','Easy can still be unpleasant'),rightNote:B('Една ситуация. Две балансирани скали.','One situation. Two balanced scales.'),strike:true,reveal:true,notes:B('В рамките на Topic 2.5. Разделете двете характеристики. Уточнете „при последната ви онлайн поръчка“. Използвайте пет степени от много трудно до много лесно и от много неприятно до много приятно, плюс „не помня“.','Within Topic 2.5. Split the two attributes. Anchor them to the last online order. Use five points from very difficult to very easy and from very unpleasant to very pleasant, plus don’t remember.')},
  {id:'survey-data',chapter:2,type:'survey',title:B('12 от 30 ≠ всички потребители','12 out of 30 ≠ all users'),subtitle:B('Колко лесно беше да разберете общата сума?','How easy was it to understand the total?'),items:[[B('Много трудно','Very difficult'),4],[B('По-скоро трудно','Somewhat difficult'),8],[B('Неутрално','Neutral'),6],[B('По-скоро лесно','Somewhat easy'),7],[B('Много лесно','Very easy'),3],[B('Не помня','Don’t remember'),2]],detail:B('40% от отговорилите съобщават затруднение','40% of respondents report difficulty'),caption:B('S1 · Измислени данни · Извадка по удобство · n = 30','S1 · Fictional data · Convenience sample · n = 30'),notes:B('В рамките на Topic 2.5. Сумата е 30. 4+8=12 трудни отговора; делим на всички 30, включително „не помня“. Не обобщаваме към всички клиенти. Посочваме подбор, брой и период. Повече отговори не поправят системно изкривяване.','Within Topic 2.5. Total is 30. Four plus eight equals 12 difficult responses, divided by all 30 including don’t remember. Do not generalise to all customers. Report recruitment, count and period. More responses cannot fix systematic bias.')},
  {id:'exercise-2',chapter:2,type:'exercise',title:B('Слушане + добър въпрос','Listening + a good question'),kicker:B('УПРАЖНЕНИЕ 02 · ПО ДВОЙКИ','EXERCISE 02 · IN PAIRS'),subtitle:B('Една реална скорошна онлайн покупка','One real, recent online purchase'),minutes:10,items:[[2,B('Изберете изследователски въпрос','Choose a research question')],[4,B('Интервю: цитат · контекст · неизвестно','Interview: quote · context · unknown')],[4,B('Разделете двойния анкетен въпрос','Split the double-barrelled survey question')]],caption:B('Практика по техника, а не пазарно изследване','Practice in technique, not market research'),notes:B('19:20–19:30. Ако няма пример с храна, използвайте друга реална покупка и отбележете различния контекст. Не измисляйте преживяване. Един отворен и един допълващ въпрос. Запис: точен цитат, контекстен факт, неизвестно. Поправете „Колко лесно и приятно беше поръчването?“ в два въпроса с балансирани скали.','19:20–19:30. If there is no food example, use another real purchase and note the context difference. Do not invent an experience. Use an open question and a follow-up. Record one quote, one context fact and one unknown. Split the double question into two neutral questions with balanced scales.')},
  {id:'discussion-2',chapter:2,type:'question',title:B('Какво всъщност знаем?','What do we actually know?'),kicker:B('БЕСЕДА · 5 МИНУТИ','DISCUSSION · 5 MINUTES'),items:[B('8 от 10 приятели харесват идеята. И сега?','8 of 10 friends like the idea. Now what?'),B('За кое неизвестно: интервю? За кое: анкета?','Which unknown needs an interview? Which needs a survey?')],notes:B('19:30–19:35. Знаем мнението на конкретните хора в конкретната ситуация. Харесване не е използване. Изборът на метод трябва да е свързан с неизвестното и решението.','19:30–19:35. We know these people’s opinions in this situation. Liking is not usage. Choose the method based on the unknown and the decision.')},
  {id:'break-2',chapter:2,type:'break',title:B('Почивка','Take a break'),subtitle:B('19:35–19:55 · Връщаме се в 19:55.','19:35–19:55 · Back at 19:55.'),minutes:20,caption:B('Кой извод бихме променили при противоречащ пример?','Which conclusion would change with conflicting evidence?'),notes:B('19:35–19:55. Обяви часа за връщане и запази 20-минутната почивка.','19:35–19:55. Announce the return time and keep the twenty-minute break.')}
);

SLIDES.push(
  {id:'laundry',chapter:3,type:'story',art:'laundry',title:B('Прането преди пътуване','Laundry before a trip'),subtitle:B('Най-ниската цена не е единственият критерий.','The lowest price isn’t the only criterion.'),bubble:B('А кога ще е сухо?','But when will it be dry?'),alt:B('Мъж с куфар и пране сравнява перални и сушене преди пътуване','A man with a suitcase and laundry compares washing and drying options before a trip'),items:[B('Алтернативи','Alternatives'),B('Критерии','Criteria'),B('Приоритет + проверка','Priority + validation')],notes:B('Блок 3 · 19:55–19:58. Пералнята на Иван се поврежда два дни преди пътуване. Сравнява обществени перални и приятел по цена, разстояние и кога ще са сухи дрехите. Insight: ключова е готовността преди заминаването. Избира услуга за пране и сушене в същия ден и звъни да провери свободен час.','Block 3 · 19:55–19:58. Ivan’s washing machine breaks two days before a trip. He compares laundries and a friend’s machine by price, distance and drying time. Insight: clothes must be ready before departure. He prioritises a same-day wash-and-dry service and calls to check availability.')},
  {id:'competitors',chapter:3,type:'flow',title:B('С кого всъщност се конкурираме?','What are we really competing with?'),items:[[B('Преки конкуренти','Direct competitors'),B('Glovo · Wolt','Glovo · Wolt')],[B('Друг начин','Another way'),B('Поръчка по телефона','Ordering by phone')],[B('Алтернатива','An alternative'),B('Обяд от вкъщи','Lunch from home')]],caption:B('Сравняваме решения за една и съща потребност','Compare solutions to the same need'),notes:B('Topic 3.1 · 4 мин. Прекият конкурент предлага сходен подход за сходен проблем и аудитория. Косвената алтернатива удовлетворява нуждата по друг начин. Проверяваме задача, информация, усилие и обещание. Не копираме функция само защото е разпространена. Glovo и Wolt са реални примери; не им приписваме учебните данни.','Topic 3.1 · 4 min. Direct competitors offer a similar approach for a similar problem and audience. Indirect alternatives meet the need differently. Compare task, information, effort and promise. Do not copy features merely because they are common. Glovo and Wolt are real examples, unrelated to the fictional data.'),source:'https://wolt.com/bg/bgr'},
  {id:'competitor-matrix',chapter:3,type:'matrix',title:B('Един сценарий. Общи критерии.','One scenario. Shared criteria.'),columns:[B('Критерий','Criterion'),B('Услуга A','Service A'),B('Услуга B','Service B')],rows:[[B('Обща цена','Total price'),B('На финалната стъпка','At the final step'),B('В кошницата','In the basket')],[B('Доставка','Delivery'),B('35–50 минути','35–50 minutes'),B('40–50 минути','40–50 minutes')],[B('След кошницата','After the basket'),B('Задължителен профил','Account required'),B('Продължаване като гост','Guest checkout')]],caption:B('C-A / C-B · Измислени услуги · Наблюдение ≠ доказан ефект','C-A / C-B · Fictional services · Observation ≠ proven impact'),notes:B('Topic 3.2 · 4 мин. Критериите произлизат от нуждата. За реален преглед фиксирайте адрес, кошница, устройство, дата и статус на вход. Неизвестно не означава липсващо. По-ранната цена не доказва по-висока конверсия; прогнозата не доказва реална скорост на доставка. При налични реални екрани използвай тях; иначе тези карти са резервният материал.','Topic 3.2 · 4 min. Derive criteria from the need. For a real review hold address, basket, device, date and login status consistent. Unknown does not mean absent. Earlier price display does not prove higher conversion; an estimate does not prove actual delivery speed. Use real screenshots if prepared, or these clearly fictional cards.')},
  {id:'evidence',chapter:3,type:'quotes',title:B('Четири гласа. Различни причини.','Four voices. Different reasons.'),quotes:[[B('I1 · Ограничен бюджет','I1 · Limited budget'),B('„Избрах обяд за 9 евро. Накрая видях общо 13. Бюджетът ми беше 11 и се отказах.“','“I chose a €9 lunch. The total was €13. My budget was €11, so I stopped.”'),B('Цена','Price')],[B('I2 · Ограничено време','I2 · Limited time'),B('„Цената ми беше ясна. Но доставката след 50 минути съвпадаше със срещата ми.“','“The price was clear. But delivery in 50 minutes clashed with my meeting.”'),B('Време','Time')],[B('I3 · Колебание, после поръчка','I3 · Hesitation, then completion'),B('„Върнах се до кошницата, за да проверя дали доставката е включена. Накрая поръчах.“','“I went back to check whether delivery was included. I eventually ordered.”'),B('Яснота','Clarity')],[B('I4 · Проблем с плащането','I4 · Payment problem'),B('„Цената и времето бяха добре. Плащането даде грешка два пъти. Поръчах по телефона.“','“Price and timing were fine. Payment failed twice. I ordered by phone.”'),B('Плащане','Payment')]],caption:B('I1–I4 · Съкратени учебни цитати · Изберете участник','I1–I4 · Shortened fictional quotes · Select a participant'),notes:B('Topic 3.3 · 5 минути с извода на следващия слайд. Покажи различните случаи чрез бутоните. Наблюдение = казано или регистрирано. Тема = група сходни наблюдения. Синтез = свързване на данни. Цитатите тук са съкратени версии на измислените цитати от program.md. Не представяй един участник като всички потребители.','Topic 3.3 · 5 minutes including the next slide. Switch between participants. An observation is something said or recorded. A theme groups related observations. Synthesis connects data. These are shortened versions of the fictional quotes in program.md. One participant does not represent every user.')},
  {id:'insight',chapter:3,type:'compare',title:B('Наблюдение → insight','Observation → insight'),labels:[B('НАБЛЮДЕНИЕ','OBSERVATION'),B('АРГУМЕНТИРАН ИЗВОД','SUPPORTED INSIGHT')],left:B('I1 и I3 се затрудняват с общата цена.','I1 and I3 struggle with the total price.'),right:B('Предвидимата цена заслужава проверка.','Price predictability deserves a test.'),leftNote:B('S1: 12 от 30 съобщават затруднение','S1: 12 of 30 report difficulty'),rightNote:B('I2 и I4 показват и други причини','I2 and I4 reveal other causes'),caption:B('Съпоставяме източници. Пазим противоречията.','Cross-check sources. Preserve the contradictions.'),notes:B('В рамките на Topic 3.3. Insight е аргументиран извод за значима нужда или проблем. Triangulation съпоставя различни източници. Не може да твърдим, че 60% се отказват заради такси: A1 не измерва причини. S1 е малка извадка по удобство. Изводът трябва да носи опора, ограничение и последица за решение.','Within Topic 3.3. An insight explains a meaningful need or problem. Triangulation compares different sources. We cannot say 60% abandon because of fees: A1 contains no causes. S1 is a small convenience sample. Include evidence, limitations and implications.')},
  {id:'value-proposition',chapter:3,type:'statement',title:B('Value proposition','Value proposition'),parts:[B('За хора с','For people with'),B('кратка обедна почивка','a short lunch break'),B('— избор на обяд с','— choose lunch with'),B('ясна обща цена','a clear total price'),B('и очакван час на доставка.','and an expected delivery time.')],caption:B('За кого → каква нужда → каква полза','For whom → which need → what benefit'),notes:B('Topic 3.4 · 3 мин. Стойностното предложение обяснява аудитория, потребност и значима полза. „Повторна поръчка“ е функция; „по-малко усилие за познат обяд“ е полза. Това е посока за проверка, не доказано конкурентно отличие. Не обещаваме точен час, ако не можем да го изпълним.','Topic 3.4 · 3 min. A value proposition explains the audience, need and meaningful benefit. Reordering is a feature; less effort for a familiar lunch is a benefit. This is a proposed direction, not proven differentiation. Do not promise an exact arrival time unless operations can deliver it.')},
  {id:'priorities',chapter:3,type:'flow',title:B('Кое да проверим първо?','What should we test first?'),items:[[B('Ефект','Impact'),B('Колко важен е проблемът?','How important is the problem?')],[B('Увереност','Confidence'),B('Колко силни са данните?','How strong is the evidence?')],[B('Усилие','Effort'),B('Какво струва проверката?','What does the test cost?')]],caption:B('Възможности: цена · доставка · плащане','Options: price · delivery · payment'),notes:B('Topic 3.5 · 4 минути с проверката на следващия слайд. Приоритизацията е обоснована последователност при ограничени ресурси. Сравняваме полза, доказателства, усилие и цена на отлагането. Не са нужни измислени числови оценки, за да проведем полезен разговор.','Topic 3.5 · 4 minutes including the next slide. Prioritisation orders work under limited resources. Compare benefits, evidence, effort and the cost of delay. We do not need invented numerical scores to have a useful discussion.')},
  {id:'validation',chapter:3,type:'compare',title:B('Разбиране ≠ бизнес ефект','Understanding ≠ business impact'),labels:[B('ПРОТОТИП','PROTOTYPE'),B('РЕАЛНА УПОТРЕБА','REAL USAGE')],left:B('„Побира ли се в бюджет от €12?“','“Does this fit a €12 budget?”'),right:B('Променя ли се конверсията?','Does conversion change?'),leftNote:B('Намира ли общата сума без помощ?','Can they find the total without help?'),rightNote:B('Еднакви правила + контролен показател','Consistent counting + a guardrail metric'),notes:B('В рамките на Topic 3.5. Първо тествай разбиране на цената в прототип. Това не доказва увеличение на продажбите. След реализация следи конверсия и оплаквания. Преди–след може да се влияе от промоции, сезон и трафик. A/B тестът случайно разпределя случаи между варианти; нужни са отделно планиране и достатъчно данни.','Within Topic 3.5. First test understanding of price in a prototype. This cannot prove a sales increase. After implementation, track conversion and complaints. Before/after comparisons can be affected by promotions, seasonality and traffic. A/B testing randomly assigns cases to variants; it requires separate planning and sufficient data.')},
  {id:'exercise-3',chapter:3,type:'exercise',title:B('Защитете един приоритет','Defend one priority'),kicker:B('УПРАЖНЕНИЕ 03 · ЕКИПИ ПО 3–4','EXERCISE 03 · TEAMS OF 3–4'),subtitle:B('Доказателство → избор → следваща проверка','Evidence → choice → next test'),minutes:12,items:[[4,B('Матрица по три общи критерия','Build a matrix with three shared criteria')],[5,B('Проблем, полза, доказателство и проверка','Problem, benefit, evidence and validation')],[3,B('Кратка защита + оставащо допускане','Short defence + remaining assumption')]],caption:B('Материали: C-A / C-B · I1–I4 · S1 · A1','Materials: C-A / C-B · I1–I4 · S1 · A1'),notes:B('20:18–20:30. Използвай пакета в program.md или учебния пакет от AI слайда. Формат: Избираме [проблем], защото [източници]. Не знаем [неизвестно]. Ще проверим [предположение] чрез [метод и показател]. Приеми различен приоритет, ако е подкрепен. Пример: цена поради I1/I3/S1, но I2/I4 показват други проблеми.','20:18–20:30. Use the program.md dataset or the AI slide’s copyable package. Format: We choose [problem] because [sources]. We do not know [unknown]. We will test [assumption] with [method and metric]. Accept different priorities when justified. Example: price based on I1/I3/S1, while I2/I4 reveal other issues.')},
  {id:'discussion-3',chapter:3,type:'question',title:B('Аргументът зад избора','The reasoning behind the choice'),kicker:B('БЕСЕДА · 5 МИНУТИ','DISCUSSION · 5 MINUTES'),items:[B('Всички конкуренти имат функцията. И ние ли трябва?','Every competitor has it. Should we build it?'),B('Кое доказателство би сменило приоритета ни?','What evidence would change our priority?')],notes:B('20:30–20:35. Масовото наличие е повод за въпрос, не достатъчен аргумент. Нови данни, по-силен проблем, техническа невъзможност или отрицателен тест могат да променят избора. Върни групата към цел → нужда → доказателство → проверка.','20:30–20:35. Widespread availability invites investigation, not automatic imitation. New evidence, a larger problem, technical constraints or a failed test may change the choice. Connect goal, need, evidence and validation.')}
);

SLIDES.push(
  {id:'ai-story',chapter:4,type:'story',art:'assistant',title:B('Помощникът с пазарската чанта','The helper with the grocery bag'),subtitle:B('Добрата задача започва с добър контекст.','A good task starts with good context.'),bubble:B('„Нещо за вечеря“?','“Something for dinner”?'),alt:B('Двама съседи в кухня, единият проверява списък, другият носи продукти','Two neighbours in a kitchen, one checking a list and the other carrying groceries'),items:[B('Контекст','Context'),B('Ясна задача','A clear task'),B('Човешка проверка','Human review')],notes:B('AI подлекция · 20:35–20:40 включва историята и организацията. „Вземи нещо за вечеря“ води до неподходящи продукти. Уточняваме трима души, един без млечни продукти, 20 минути за готвене и наличното в хладилника. Помощникът предлага, човекът проверява. Аналогията обяснява процеса; AI не е човешкият помощник.','AI mini-lecture · 20:35–20:40 includes this story and the workflow. “Get something for dinner” yields unsuitable groceries. Specify three people, one dairy-free, 20 minutes to cook and what is already in the fridge. The helper proposes; the person checks. This is a workflow analogy, not a claim that AI is human.')},
  {id:'ai-workflow',chapter:4,type:'flow',title:B('Организация на работата с AI','Organising work with AI'),items:[[B('Въпрос','Question'),B('Какво решаваме?','What are we deciding?')],[B('Контекст','Context'),B('Цели + ограничения','Goals + constraints')],[B('Източници','Sources'),B('Данни с идентификатори','Data with identifiers')],[B('Задача','Task'),B('Малък, ясен резултат','A small, clear output')],[B('Проверка','Review'),B('Опора за всяко твърдение','Evidence for each claim')]],caption:B('Проверените изводи се пазят отделно от черновите','Keep reviewed conclusions separate from drafts'),notes:B('В рамките на 20:35–20:40. Генеративен AI създава съдържание по инструкции и контекст. LLM обработва и генерира език. Prompt е инструкцията; output е резултатът. Организирай контекст, оригинални източници, работни чернови и проверени изводи. Един проект може да пази общи файлове и инструкции.','Within 20:35–20:40. Generative AI creates content from instructions and context. An LLM processes and generates language. A prompt is an instruction; output is the result. Organise context, original sources, drafts and reviewed conclusions. A project can keep shared files and instructions.'),source:'https://learn.chatgpt.com/docs/projects'},
  {id:'ai-tools',chapter:4,type:'tools',title:B('Инструмент според задачата','Choose the tool for the task'),items:[[B('ChatGPT / Claude','ChatGPT / Claude'),B('Чернови, въпроси, критичен преглед и уеб проучване','Drafts, questions, critical review and web research'),B('Проверявай първоизточниците','Check the original sources')],[B('NotebookLM','NotebookLM'),B('Въпроси и синтез върху подбран набор материали','Questions and synthesis over selected materials'),B('Отваряй цитата в контекст','Open the quote in context')],[B('Dovetail','Dovetail'),B('Изследователско хранилище, теми и проследими изводи','Research repository, themes and traceable insights'),B('Пази различията между участниците','Preserve differences between participants')]],caption:B('Достъпът и функциите зависят от акаунта · Един инструмент е достатъчен за демонстрацията','Access and features vary by account · One tool is enough for the demo'),notes:B('20:40–20:46. ChatGPT/Claude: целите от блок 1, въпросите от блок 2, синтезът от блок 3. NotebookLM / Gemini Notebook: работа с конкретни материали и препратки. Dovetail: повече интервюта и работа в екип. Препратката не гарантира вярно тълкуване. Използвай разрешени инструменти. Документация: learn.chatgpt.com/docs/web-search; support.claude.com/en/articles/11088861-use-research-on-claude; support.google.com/gemininotebook/answer/16179559; dovetail.com/solutions/research-repository/.','20:40–20:46. ChatGPT/Claude: goals from block 1, questions from block 2 and synthesis from block 3. NotebookLM / Gemini Notebook: selected sources and citations. Dovetail: larger research collections and teamwork. Citations do not guarantee correct interpretation. Use approved tools. Documentation: learn.chatgpt.com/docs/web-search; support.claude.com/en/articles/11088861-use-research-on-claude; support.google.com/gemininotebook/answer/16179559; dovetail.com/solutions/research-repository/.'),source:'https://learn.chatgpt.com/docs/web-search'},
  {id:'ai-demo',chapter:4,type:'demo',title:B('Една задача. Проверим резултат.','One task. A verifiable result.'),kicker:B('ДЕМОНСТРАЦИЯ · 8 МИНУТИ','DEMONSTRATION · 8 MINUTES'),items:[B('Използвай само предоставените учебни данни.','Use only the supplied fictional teaching data.'),B('Раздели наблюдения, интерпретации и хипотези.','Separate observations, interpretations and hypotheses.'),B('Посочи източник, ограничение и следваща проверка.','Name a source, a limitation and the next test.')],caption:B('Всички данни са измислени · Не са нужни лични данни','All data is fictional · No personal data needed'),notes:B('20:46–20:54, включително следващия слайд. 1 мин контекст; 2 мин prompt/резултат; 3 мин проверка; 2 мин редакция. Бутонът копира задачата заедно с целия пакет от учебни данни, в избрания език. Постави го в избрания инструмент. При бавен отговор премини към резервния пример. Проверявай цитат, знаменател, обхват и противоречащ случай.','20:46–20:54, including the next slide. One minute context; two prompt/result; three review; two revision. The button copies the prompt and complete fictional dataset in the selected language. Paste into your chosen tool. If slow, use the fallback example. Check the quote, denominator, scope and conflicting case.')},
  {id:'ai-claim',chapter:4,type:'compare',title:B('Убедително ≠ вярно','Convincing ≠ correct'),labels:[B('УЧЕБЕН ГРЕШЕН ОТГОВОР','DELIBERATELY WRONG EXAMPLE'),B('ПОДКРЕПЕН ИЗВОД','SUPPORTED CONCLUSION')],left:B('„60% се отказват заради скрити такси.“','“60% abandon because of hidden fees.”'),right:B('„60% не завършват. Причините не са измерени.“','“60% do not finish. Causes were not measured.”'),leftNote:B('A1 не съдържа причини','A1 does not contain causes'),rightNote:B('I1/I3 и S1 насочват към проверка на цената','I1/I3 and S1 suggest testing price clarity'),strike:true,reveal:true,caption:B('Предварително написан пример, не реален резултат от AI инструмент','A pre-written example, not an actual AI tool response'),notes:B('Резервен пример в демонстрацията. Не приписвай тази грешка на конкретен инструмент. Ако живият отговор е верен, покажи как го проверяваш. A1 измерва незавършване, не причина. I2 и I4 описват други проблеми. 50% е цел, не гарантиран ефект.','Fallback example within the demo. Do not attribute this error to a tool. If the live answer is correct, show how you verified it. A1 measures non-completion, not causes. I2 and I4 describe other issues. 50% is a target, not a guaranteed effect.')},
  {id:'ai-productivity',chapter:4,type:'list',title:B('Време до използваем резултат','Time to a usable result'),kicker:B('ПРОДУКТИВНОСТ','PRODUCTIVITY'),items:[[B('Подготовка + генериране','Preparation + generation'),B('Контекст, ясна задача, първа чернова','Context, a clear task, a first draft')],[B('Проверка + редакция','Review + revision'),B('Източници, числа, липси и противоречия','Sources, numbers, gaps and contradictions')],[B('Повторна употреба','Reuse'),B('Запази работещите инструкции и примери','Keep useful instructions and examples')]],caption:B('Бърза чернова не означава автоматично спестено време','A fast draft does not automatically save time'),notes:B('20:54–20:58, със следващия слайд. AI може да ускори чернови, групиране на бележки, критика и споделяне. Сравнявай общото време до използваем резултат при сходни задачи. Следи съществени корекции и проверими твърдения. Не обещавай фиксирана печалба в продуктивността.','20:54–20:58, including the next slide. AI can speed drafts, grouping, critique and communication. Compare total time to a usable result on similar tasks. Track material corrections and verifiable claims. Do not promise a fixed productivity gain.')},
  {id:'ai-boundaries',chapter:4,type:'flow',title:B('Преценката остава наша','Judgement stays with us'),items:[[B('Истински хора','Real people'),B('Синтетичен отговор ≠ изследване','Synthetic responses ≠ research')],[B('Разрешени данни','Approved data'),B('Обезличаване + подходящ достъп','De-identification + appropriate access')],[B('Проверени изводи','Reviewed insights'),B('Правдоподобно ≠ доказано','Plausible ≠ proven')]],notes:B('Халюцинация = правдоподобно, но невярно или неподкрепено съдържание. Синтетичният участник може да служи за репетиция, не е реален участник. Премахване само на име не е достатъчно, ако други детайли идентифицират. AI не поправя автоматично лоша извадка и не доказва бизнес ефект чрез препоръка.','Hallucination means plausible but false or unsupported content. A synthetic participant may support rehearsal, but is not a real research participant. Removing names is insufficient when other details identify people. AI cannot automatically fix biased sampling or prove business impact through a recommendation.')},
  {id:'ai-discussion',chapter:4,type:'question',title:B('Какво ще възложите на AI?','What would you delegate to AI?'),kicker:B('КРАТЪК РАЗГОВОР · 2 МИНУТИ','SHORT DISCUSSION · 2 MINUTES'),items:[B('Коя конкретна стъпка?','Which specific step?'),B('Как ще проверите резултата?','How will you check the result?')],notes:B('20:58–21:00. 20–30 секунди за избор, два кратки отговора. Изискай конкретна проверка: цитат, пресмятане, първоизточник или преглед на въпросите.','20:58–21:00. Allow 20–30 seconds to choose, then take two short answers. Require a specific check: quote, calculation, original source or question review.')},
  {id:'summary',chapter:5,type:'summary',title:B('Пет опори за следващия проект','Five anchors for your next project'),items:[[B('Цел','Goal'),B('Какъв резултат има значение?','Which outcome matters?')],[B('Нужда','Need'),B('Какво иска да постигне човекът?','What is the person trying to achieve?')],[B('Доказателство','Evidence'),B('Откъде знаем това?','How do we know?')],[B('Избор','Choice'),B('Какво ще направим първо?','What will we do first?')],[B('Проверка','Validation'),B('Как ще разберем дали помага?','How will we know it helps?')]],notes:B('21:00–21:03. Върни се към незавършените поръчки. Уточнихме целта, отделихме нуждата от функцията, избрахме изследване, сравнихме алтернативи и предложихме проверка.','21:00–21:03. Return to abandoned orders. We clarified the goal, separated needs from features, chose research, compared alternatives and proposed validation.')},
  {id:'questions',chapter:5,type:'question',title:B('Вашите въпроси','Your questions'),kicker:B('ФИНАЛЕН РАЗГОВОР · 5 МИНУТИ','FINAL DISCUSSION · 5 MINUTES'),items:[B('Коя стъпка най-лесно прескачаме под натиск?','Which step do we skip under pressure?'),B('Каква грешка може да последва?','What mistake could follow?')],notes:B('21:03–21:08. Първо отговори на отложените въпроси. Използвай двата въпроса на екрана, ако няма други. По-широките теми могат да се обсъдят отделно след лекцията.','21:03–21:08. Address parked questions first. Use these prompts if there are none. Broader topics can be discussed separately after the lecture.')},
  {id:'exit-ticket',chapter:5,type:'list',title:B('Три изречения за финал','Three sentences to finish'),kicker:B('ИЗХОДЕН БИЛЕТ · 2 МИНУТИ','EXIT TICKET · 2 MINUTES'),items:[B('Бих дал приоритет на…','I would prioritise…'),B('Основанието ми е… Ограничението е…','My evidence is… Its limitation is…'),B('Следващото, което ще проверя, е…','The next thing I will test is…')],notes:B('21:08–21:10. Индивидуален отговор, не общ разговор. Проверяваме дали всеки може да свърже решение, доказателство, ограничение и следваща проверка.','21:08–21:10. Individual writing, not a group discussion. Check that everyone can connect a decision, evidence, limitations and the next test.')},
  {id:'thank-you',chapter:5,type:'finish',title:B('Преди пикселите —\nпо-добри въпроси.','Before pixels —\nbetter questions.'),subtitle:B('Ясна причина. Опора в данни. Начин за проверка.','A clear reason. Supporting evidence. A way to test.'),caption:B('БЛАГОДАРЯ · TELERIK ACADEMY','THANK YOU · TELERIK ACADEMY'),notes:B('Заключителна реплика, без допълнително време: „Доброто стратегическо решение има ясна причина, опора в данни и начин да бъде проверено.“','Closing line, without adding time: “A good strategic decision has a clear reason, supporting evidence and a way to test it.”')}
);
